<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">	&quot;ttl_minutes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: config.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MYANMAR_PAYMENTS_FORM_TTL_MINUTES&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
